// CodeList is the Go interface backing the Gom sort CodeList.
type CodeList interface {
	sharedobjects.Term
	isCodeList()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	IsConsconcCode() bool
	IsEmptyconcCode() bool
	GetHeadconcCode() Code
	GetTailconcCode() CodeList
	Length() int
	Reverse() CodeList
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// CodeListFromTerm is Java Gom's CodeList.fromTerm(trm).
func CodeListFromTerm(trm aterm.ATerm) CodeList {
	return CodeListFromTermConv(trm, aterm.IdConverter{})
}

// CodeListFromTermConv is Java Gom's CodeList.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func CodeListFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) CodeList {
	converted := conv.Convert(trm)
	var results []CodeList
	if r, ok := fromTermConcCodeCodeList(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a CodeList", trm), IllegalArgument: true})
	}
	return results[0]
}

// CodeListFromString is Java Gom's CodeList.fromString(s).
func CodeListFromString(s string) CodeList { return CodeListFromTerm(aterm.GetInstance().Parse(s)) }

// CodeListFromStream is Java Gom's CodeList.fromStream(stream) (an IOException is
// the error).
func CodeListFromStream(stream io.Reader) (CodeList, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return CodeListFromTerm(at), nil
}

// ConcCodeCodeList is the term type of the variadic operator `concCode(...)` of sort CodeList
// (Java's abstract class concCode): a maximally-shared cons cell (Java's
// ConsconcCode: a head and a tail) or the empty list (Java's EmptyconcCode).
type ConcCodeCodeList struct {
	head  Code
	tail  CodeList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcCodeCodeList) isCodeList() {}

func (t *ConcCodeCodeList) Hash() uint32 { return t.hash }

func (t *ConcCodeCodeList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcCodeCodeList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcCodeCodeList) Duplicate() sharedobjects.Term {
	return &ConcCodeCodeList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new Code[]{}): a last tail
// that is not a list (of sort CodeList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcCodeCodeList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur CodeList = t
	for {
		c, ok := cur.(*ConcCodeCodeList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcCodeCodeList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concCode list is not a Code", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcCodeCodeList) ChildCount() int { return len(t.elements()) }

func (t *ConcCodeCodeList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcCodeCodeList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcCodeCodeList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcCodeFromArray(children).
func (t *ConcCodeCodeList) SetChildren(children []any) any {
	args := make([]Code, len(children))
	for i, c := range children {
		args[i] = c.(Code)
	}
	return MakeConcCode(args...)
}

func (t *ConcCodeCodeList) String() string {
	var b strings.Builder
	b.WriteString("concCode(")
	var cur CodeList = t
	for {
		c, ok := cur.(*ConcCodeCodeList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcCode is Java Gom's ConsconcCode.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcCode(head Code, tail CodeList) CodeList {
	proto := &ConcCodeCodeList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsconcCode"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcCodeCodeList)
}

// realMakeEmptyConcCode is Java Gom's EmptyconcCode.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcCode() CodeList {
	proto := &ConcCodeCodeList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcCode"), nil)}
	return factory.Build(proto).(*ConcCodeCodeList)
}

// RawConcCode builds the concCode list holding exactly args, without construction
// hook.
func RawConcCode(args ...Code) CodeList {
	l := realMakeEmptyConcCode()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcCode(args[i], l)
	}
	return l
}

// EmptyConcCode is Java Gom's EmptyconcCode.make(): the empty concCode list, after the
// construction hooks.
func EmptyConcCode() CodeList {
	return realMakeEmptyConcCode()
}

// ConsConcCode is Java Gom's ConsconcCode.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsConcCode(head Code, tail CodeList) CodeList {
	return RealMakeConsConcCode(head, tail)
}

// MakeConcCode builds the list of args as Tom's `concCode(args…)` does: from EmptyConcCode,
// by ConsConcCode, through the construction hooks (Java's concCode.fromArray).
func MakeConcCode(args ...Code) CodeList {
	var l CodeList = EmptyConcCode()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcCode(args[i], l)
	}
	return l
}

// ConcCodeFromArray is Java Gom's concCode.fromArray(array).
func ConcCodeFromArray(array []Code) CodeList { return MakeConcCode(array...) }

