// SymbolName is the symbol of the Java term: ConsconcCode or EmptyconcCode.
func (t *ConcCodeCodeList) SymbolName() string {
	if t.empty {
		return "EmptyconcCode"
	}
	return "ConsconcCode"
}

func (t *ConcCodeCodeList) IsConsconcCode() bool  { return !t.empty }
func (t *ConcCodeCodeList) IsEmptyconcCode() bool { return t.empty }

func (t *ConcCodeCodeList) GetHeadconcCode() Code {
	if t.empty {
		panic(&aterm.GomError{Msg: "This CodeList has no HeadconcCode"})
	}
	return t.head
}
func (t *ConcCodeCodeList) GetTailconcCode() CodeList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This CodeList has no TailconcCode"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concCode list counts as one element).
func (t *ConcCodeCodeList) Length() int {
	res := 0
	var tl CodeList = t
	for {
		c, ok := tl.(*ConcCodeCodeList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcCodeCodeList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concCode list.
func (t *ConcCodeCodeList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur CodeList = t
	for {
		c, ok := cur.(*ConcCodeCodeList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcCodeCodeList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcCode
// (through the hooks).
func (t *ConcCodeCodeList) Reverse() CodeList {
	if t.empty {
		return t
	}
	var cur CodeList = t
	var rev CodeList = EmptyConcCode()
	for {
		c, ok := cur.(*ConcCodeCodeList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcCode(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcCode (through the hooks).
func (t *ConcCodeCodeList) Append(element Code) CodeList {
	var heads []Code
	var cur CodeList = t
	for {
		c, ok := cur.(*ConcCodeCodeList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res CodeList
	if c, ok := cur.(*ConcCodeCodeList); ok && c.empty {
		res = ConsConcCode(element, cur)
	} else {
		res = ConsConcCode(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcCode(heads[i], res)
	}
	return res
}

func (t *ConcCodeCodeList) CompareTo(o any) int {
	for {
		ao := o.(CodeList)
		if ao == CodeList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcCodeCodeList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcCodeCodeList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcCodeCodeList) CompareToLPO(o any) int {
	for {
		ao := o.(CodeList)
		if ao == CodeList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcCodeCodeList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcCodeCodeList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcCodeCodeList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Code
	var cur CodeList = t
	for {
		c, ok := cur.(*ConcCodeCodeList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcCodeCodeList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcCodeCodeList is Java Gom's concCode.fromTerm: an application of concCode, or a
// list (of ToATerm), of convertible elements.
func fromTermConcCodeCodeList(trm aterm.ATerm, conv aterm.ATermConverter) (res CodeList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concCode" {
		elems := make([]Code, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CodeFromTermConv(a, conv)
		}
		return MakeConcCode(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concCode (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Code
		for !list.IsEmpty() {
			elems = append(elems, CodeFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcCode(elems...), true
	}
	return nil, false
}

