func (t *TomIncludeCode) CompareTo(o any) int {
	ao := o.(Code)
	if ao == Code(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*TomIncludeCode)
	if c := t.CodeList.CompareTo(tco.CodeList); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

