// ToATerm is the ATerm of the term: an application of TomInclude.
func (t *TomIncludeCode) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("TomInclude", 1, false), t.CodeList.ToATerm())
}

// fromTermTomIncludeCode is Java Gom's TomInclude.fromTerm: an unquoted application of
// TomInclude whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermTomIncludeCode(trm aterm.ATerm, conv aterm.ATermConverter) (Code, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "TomInclude" && !appl.GetAFun().IsQuoted() {
		return MakeTomInclude(CodeListFromTermConv(appl.GetArgument(0), conv)), true
	}
	return nil, false
}

// BQTermList is the Go interface backing the Gom sort BQTermList.
type BQTermList interface {
	sharedobjects.Term
	isBQTermList()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	IsConsconcBQTerm() bool
	IsEmptyconcBQTerm() bool
	GetHeadconcBQTerm() BQTerm
	GetTailconcBQTerm() BQTermList
	Length() int
	Reverse() BQTermList
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// BQTermListFromTerm is Java Gom's BQTermList.fromTerm(trm).
func BQTermListFromTerm(trm aterm.ATerm) BQTermList {
	return BQTermListFromTermConv(trm, aterm.IdConverter{})
}

// BQTermListFromTermConv is Java Gom's BQTermList.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func BQTermListFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) BQTermList {
	converted := conv.Convert(trm)
	var results []BQTermList
	if r, ok := fromTermConcBQTermBQTermList(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a BQTermList", trm), IllegalArgument: true})
	}
	return results[0]
}

// BQTermListFromString is Java Gom's BQTermList.fromString(s).
func BQTermListFromString(s string) BQTermList {
	return BQTermListFromTerm(aterm.GetInstance().Parse(s))
}

// BQTermListFromStream is Java Gom's BQTermList.fromStream(stream) (an IOException is
// the error).
func BQTermListFromStream(stream io.Reader) (BQTermList, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return BQTermListFromTerm(at), nil
}

// ConcBQTermBQTermList is the term type of the variadic operator `concBQTerm(...)` of sort BQTermList
// (Java's abstract class concBQTerm): a maximally-shared cons cell (Java's
// ConsconcBQTerm: a head and a tail) or the empty list (Java's EmptyconcBQTerm).
type ConcBQTermBQTermList struct {
	head  BQTerm
	tail  BQTermList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcBQTermBQTermList) isBQTermList() {}

func (t *ConcBQTermBQTermList) Hash() uint32 { return t.hash }

func (t *ConcBQTermBQTermList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcBQTermBQTermList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcBQTermBQTermList) Duplicate() sharedobjects.Term {
	return &ConcBQTermBQTermList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new BQTerm[]{}): a last tail
// that is not a list (of sort BQTermList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcBQTermBQTermList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur BQTermList = t
	for {
		c, ok := cur.(*ConcBQTermBQTermList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcBQTermBQTermList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concBQTerm list is not a BQTerm", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcBQTermBQTermList) ChildCount() int { return len(t.elements()) }

func (t *ConcBQTermBQTermList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcBQTermBQTermList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcBQTermBQTermList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcBQTermFromArray(children).
func (t *ConcBQTermBQTermList) SetChildren(children []any) any {
	args := make([]BQTerm, len(children))
	for i, c := range children {
		args[i] = c.(BQTerm)
	}
	return MakeConcBQTerm(args...)
}

func (t *ConcBQTermBQTermList) String() string {
	var b strings.Builder
	b.WriteString("concBQTerm(")
	var cur BQTermList = t
	for {
		c, ok := cur.(*ConcBQTermBQTermList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcBQTerm is Java Gom's ConsconcBQTerm.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcBQTerm(head BQTerm, tail BQTermList) BQTermList {
	proto := &ConcBQTermBQTermList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsconcBQTerm"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcBQTermBQTermList)
}

// realMakeEmptyConcBQTerm is Java Gom's EmptyconcBQTerm.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcBQTerm() BQTermList {
	proto := &ConcBQTermBQTermList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcBQTerm"), nil)}
	return factory.Build(proto).(*ConcBQTermBQTermList)
}

// RawConcBQTerm builds the concBQTerm list holding exactly args, without construction
// hook.
func RawConcBQTerm(args ...BQTerm) BQTermList {
	l := realMakeEmptyConcBQTerm()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcBQTerm(args[i], l)
	}
	return l
}

// EmptyConcBQTerm is Java Gom's EmptyconcBQTerm.make(): the empty concBQTerm list, after the
// construction hooks.
func EmptyConcBQTerm() BQTermList {
	return realMakeEmptyConcBQTerm()
}

// ConsConcBQTerm is Java Gom's ConsconcBQTerm.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsConcBQTerm(head BQTerm, tail BQTermList) BQTermList {
	return RealMakeConsConcBQTerm(head, tail)
}

// MakeConcBQTerm builds the list of args as Tom's `concBQTerm(args…)` does: from EmptyConcBQTerm,
// by ConsConcBQTerm, through the construction hooks (Java's concBQTerm.fromArray).
func MakeConcBQTerm(args ...BQTerm) BQTermList {
	var l BQTermList = EmptyConcBQTerm()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcBQTerm(args[i], l)
	}
	return l
}

// ConcBQTermFromArray is Java Gom's concBQTerm.fromArray(array).
func ConcBQTermFromArray(array []BQTerm) BQTermList { return MakeConcBQTerm(array...) }

