// VisitConcBQTerm is the `_concBQTerm` slot-visit strategy: when subject is `concBQTerm`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `concBQTerm`.
type VisitConcBQTerm struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitConcBQTerm builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitConcBQTerm(args ...sl.Strategy) *VisitConcBQTerm {
	return &VisitConcBQTerm{args: args}
}

func (s *VisitConcBQTerm) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcBQTermBQTermList); !ok {
		return subject, sl.ErrVisitFailure
	}
	// Variadic alt: visit every element with args[0] (Java's
	// `_concX` invokes the sub-strategy on each list element).
	if len(s.args) == 0 {
		return subject, nil
	}
	count := intro.GetChildCount(subject)
	var newChildren []any
	for i := 0; i < count; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[0].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitConcBQTerm) ChildCount() int                 { return len(s.args) }
func (s *VisitConcBQTerm) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitConcBQTerm) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitConcBQTerm) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcBQTermBQTermList); !ok {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, true)
}
func (s *VisitConcBQTerm) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitConcBQTerm) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitConcBQTerm)(nil)

// SymbolName is the symbol of the Java term: ConsconcBQTerm or EmptyconcBQTerm.
func (t *ConcBQTermBQTermList) SymbolName() string {
	if t.empty {
		return "EmptyconcBQTerm"
	}
	return "ConsconcBQTerm"
}

func (t *ConcBQTermBQTermList) IsConsconcBQTerm() bool  { return !t.empty }
func (t *ConcBQTermBQTermList) IsEmptyconcBQTerm() bool { return t.empty }

func (t *ConcBQTermBQTermList) GetHeadconcBQTerm() BQTerm {
	if t.empty {
		panic(&aterm.GomError{Msg: "This BQTermList has no HeadconcBQTerm"})
	}
	return t.head
}
func (t *ConcBQTermBQTermList) GetTailconcBQTerm() BQTermList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This BQTermList has no TailconcBQTerm"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concBQTerm list counts as one element).
func (t *ConcBQTermBQTermList) Length() int {
	res := 0
	var tl BQTermList = t
	for {
		c, ok := tl.(*ConcBQTermBQTermList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcBQTermBQTermList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concBQTerm list.
func (t *ConcBQTermBQTermList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur BQTermList = t
	for {
		c, ok := cur.(*ConcBQTermBQTermList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcBQTermBQTermList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcBQTerm
// (through the hooks).
func (t *ConcBQTermBQTermList) Reverse() BQTermList {
	if t.empty {
		return t
	}
	var cur BQTermList = t
	var rev BQTermList = EmptyConcBQTerm()
	for {
		c, ok := cur.(*ConcBQTermBQTermList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcBQTerm(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcBQTerm (through the hooks).
func (t *ConcBQTermBQTermList) Append(element BQTerm) BQTermList {
	var heads []BQTerm
	var cur BQTermList = t
	for {
		c, ok := cur.(*ConcBQTermBQTermList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res BQTermList
	if c, ok := cur.(*ConcBQTermBQTermList); ok && c.empty {
		res = ConsConcBQTerm(element, cur)
	} else {
		res = ConsConcBQTerm(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcBQTerm(heads[i], res)
	}
	return res
}

func (t *ConcBQTermBQTermList) CompareTo(o any) int {
	for {
		ao := o.(BQTermList)
		if ao == BQTermList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcBQTermBQTermList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcBQTermBQTermList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcBQTermBQTermList) CompareToLPO(o any) int {
	for {
		ao := o.(BQTermList)
		if ao == BQTermList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcBQTermBQTermList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcBQTermBQTermList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcBQTermBQTermList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []BQTerm
	var cur BQTermList = t
	for {
		c, ok := cur.(*ConcBQTermBQTermList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcBQTermBQTermList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcBQTermBQTermList is Java Gom's concBQTerm.fromTerm: an application of concBQTerm, or a
// list (of ToATerm), of convertible elements.
func fromTermConcBQTermBQTermList(trm aterm.ATerm, conv aterm.ATermConverter) (res BQTermList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concBQTerm" {
		elems := make([]BQTerm, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = BQTermFromTermConv(a, conv)
		}
		return MakeConcBQTerm(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concBQTerm (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []BQTerm
		for !list.IsEmpty() {
			elems = append(elems, BQTermFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcBQTerm(elems...), true
	}
	return nil, false
}

