// BQTermFromString is Java Gom's BQTerm.fromString(s).
func BQTermFromString(s string) BQTerm { return BQTermFromTerm(aterm.GetInstance().Parse(s)) }

// BQTermFromStream is Java Gom's BQTerm.fromStream(stream) (an IOException is
// the error).
func BQTermFromStream(stream io.Reader) (BQTerm, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return BQTermFromTerm(at), nil
}

