func (t *BQApplBQTerm) CompareTo(o any) int {
	ao := o.(BQTerm)
	if ao == BQTerm(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*BQApplBQTerm)
	if c := t.Options.CompareTo(tco.Options); c != 0 {
		return c
	}
	if c := t.AstName.CompareTo(tco.AstName); c != 0 {
		return c
	}
	if c := t.Args.CompareTo(tco.Args); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *BQApplBQTerm) CompareToLPO(o any) int {
	ao := o.(BQTerm)
	if ao == BQTerm(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*BQApplBQTerm)
	if c := t.Options.CompareToLPO(tco.Options); c != 0 {
		return c
	}
	if c := t.AstName.CompareToLPO(tco.AstName); c != 0 {
		return c
	}
	if c := t.Args.CompareToLPO(tco.Args); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of BQAppl.
func (t *BQApplBQTerm) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("BQAppl", 3, false), t.Options.ToATerm(), t.AstName.ToATerm(), t.Args.ToATerm())
}

// fromTermBQApplBQTerm is Java Gom's BQAppl.fromTerm: an unquoted application of
// BQAppl whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermBQApplBQTerm(trm aterm.ATerm, conv aterm.ATermConverter) (BQTerm, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "BQAppl" && !appl.GetAFun().IsQuoted() {
		return MakeBQAppl(OptionListFromTermConv(appl.GetArgument(0), conv), TomNameFromTermConv(appl.GetArgument(1), conv), BQTermListFromTermConv(appl.GetArgument(2), conv)), true
	}
	return nil, false
}

