// Length is Java's length(): the number of elements of the list (a
// tail that is not a Composite list counts as one element).
func (t *CompositeBQTerm) Length() int {
	res := 0
	var tl BQTerm = t
	for {
		c, ok := tl.(*CompositeBQTerm)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*CompositeBQTerm); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a Composite list.
func (t *CompositeBQTerm) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur BQTerm = t
	for {
		c, ok := cur.(*CompositeBQTerm)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*CompositeBQTerm); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsComposite
// (through the hooks).
func (t *CompositeBQTerm) Reverse() BQTerm {
	if t.empty {
		return t
	}
	var cur BQTerm = t
	var rev BQTerm = EmptyComposite()
	for {
		c, ok := cur.(*CompositeBQTerm)
		if !ok || c.empty {
			break
		}
		rev = ConsComposite(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsComposite (through the hooks).
func (t *CompositeBQTerm) Append(element CompositeMember) BQTerm {
	var heads []CompositeMember
	var cur BQTerm = t
	for {
		c, ok := cur.(*CompositeBQTerm)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res BQTerm
	if c, ok := cur.(*CompositeBQTerm); ok && c.empty {
		res = ConsComposite(element, cur)
	} else {
		res = ConsComposite(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsComposite(heads[i], res)
	}
	return res
}

func (t *CompositeBQTerm) CompareTo(o any) int {
	for {
		ao := o.(BQTerm)
		if ao == BQTerm(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*CompositeBQTerm)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*CompositeBQTerm)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *CompositeBQTerm) CompareToLPO(o any) int {
	for {
		ao := o.(BQTerm)
		if ao == BQTerm(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*CompositeBQTerm)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*CompositeBQTerm)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *CompositeBQTerm) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []CompositeMember
	var cur BQTerm = t
	for {
		c, ok := cur.(*CompositeBQTerm)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*CompositeBQTerm); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermCompositeBQTerm is Java Gom's Composite.fromTerm: an application of Composite, or a
// list (of ToATerm), of convertible elements.
func fromTermCompositeBQTerm(trm aterm.ATerm, conv aterm.ATermConverter) (res BQTerm, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "Composite" {
		elems := make([]CompositeMember, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = CompositeMemberFromTermConv(a, conv)
		}
		return MakeComposite(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a Composite (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []CompositeMember
		for !list.IsEmpty() {
			elems = append(elems, CompositeMemberFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeComposite(elems...), true
	}
	return nil, false
}

