func (t *ListTailBQTerm) CompareTo(o any) int {
	ao := o.(BQTerm)
	if ao == BQTerm(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ListTailBQTerm)
	if c := t.Opname.CompareTo(tco.Opname); c != 0 {
		return c
	}
	if c := t.Variable.CompareTo(tco.Variable); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *ListTailBQTerm) CompareToLPO(o any) int {
	ao := o.(BQTerm)
	if ao == BQTerm(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*ListTailBQTerm)
	if c := t.Opname.CompareToLPO(tco.Opname); c != 0 {
		return c
	}
	if c := t.Variable.CompareToLPO(tco.Variable); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of ListTail.
func (t *ListTailBQTerm) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("ListTail", 2, false), t.Opname.ToATerm(), t.Variable.ToATerm())
}

// fromTermListTailBQTerm is Java Gom's ListTail.fromTerm: an unquoted application of
// ListTail whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermListTailBQTerm(trm aterm.ATerm, conv aterm.ATermConverter) (BQTerm, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "ListTail" && !appl.GetAFun().IsQuoted() {
		return MakeListTail(TomNameFromTermConv(appl.GetArgument(0), conv), BQTermFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}
